# frozen_string_literal: true

# Generated by Descant: acceptance tests.

require "rails_helper"

RSpec.describe "Api::V1::Cli::TimesheetEntries through the entry gateway", type: :request do
  let(:company) { create(:company, plan_tier: "free") }
  let(:user) { create(:user, current_workspace_id: company.id) }
  let(:colleague) { create(:user, current_workspace_id: company.id) }
  let(:project) { create(:project, billable: true, client: create(:client, company:)) }
  let(:cli_token) { CliSession.issue_for(user:, company:).last }
  let(:cli_headers) { cli_auth_headers(cli_token) }
  let(:caller_role) { "employee" }
  let(:fake) { TimekeepingContract::FakeTimekeeping.new(token_public_key: timekeeping_key_pair.public_key) }

  before do
    create(:employment, company:, user:)
    user.add_role caller_role.to_sym, company
    create(:project_member, project:, user:)
  end

  context "with Timekeeping owning the entries" do
    around { |example| with_forwarded_timekeeping_env { example.run } }

    before do
      create(:employment, company:, user: colleague)
      colleague.add_role :employee, company
      create(:project_member, project:, user: colleague)
      arrange_forwarded_timekeeping(fake, company:, users: { user => caller_role, colleague => "employee" }, project:)
    end

    def cli_write_count(method)
      fake.requests.count { |request| request[:method] == method }
    end

    # An admin would pass a company-wide lookup, so for that row only the own-entries scope can refuse the
    # colleague's entry. Each row first edits the caller's own entry, so the scope must tell the two apart
    # within one session.
    %w[employee admin].each do |role|
      context "when the caller is an #{role}" do
        let(:caller_role) { role }

        # "The CLI keeps its own-entries scope: the lookup is restricted to `user_id` equal to the actor and to the current company."
        # "A forwarded CLI update of another user's entry gets 404."
        it "forwards an update of the caller's own entry but answers 404 to an update or destroy of a colleague's entry and forwards no write for it" do
          own_entry_id = fake.add_entry(company_id: company.id, user_id: user.id, project_id: project.id,
                                        work_date: Date.current.iso8601).fetch("id")
          colleague_entry_id = fake.add_entry(company_id: company.id, user_id: colleague.id, project_id: project.id,
                                              work_date: Date.current.iso8601, note: "Colleague's work").fetch("id")
          update_params = {
            timesheet_entry: { project_id: project.id, duration_minutes: 45, work_date: Date.current.iso8601, note: "Edited from CLI" }
          }

          send_request :patch, api_v1_cli_timesheet_entry_path(own_entry_id), params: update_params, headers: cli_headers

          expect(response).to have_http_status(:ok)
          expect(fake.stored_entry(own_entry_id)["note"]).to eq("Edited from CLI")

          patches_before = cli_write_count("PATCH")
          outbox_before = fake.outbox.size
          send_request :patch, api_v1_cli_timesheet_entry_path(colleague_entry_id), params: update_params,
                                                                                    headers: cli_headers

          expect(response).to have_http_status(:not_found)
          expect(cli_write_count("PATCH")).to eq(patches_before)
          expect(fake.outbox.size).to eq(outbox_before)
          expect(fake.stored_entry(colleague_entry_id)).to include("note" => "Colleague's work", "duration" => 60.0)

          # Counting every DELETE also rules out a replay-only DELETE (`Idempotency-Replay: only`).
          deletes_before = cli_write_count("DELETE")
          send_request :delete, api_v1_cli_timesheet_entry_path(colleague_entry_id), headers: cli_headers

          expect(response).to have_http_status(:not_found)
          expect(cli_write_count("DELETE")).to eq(deletes_before)
          expect(fake.outbox.size).to eq(outbox_before)
          expect(fake.stored_entry(colleague_entry_id)).to include("note" => "Colleague's work", "duration" => 60.0,
                                                                   "discarded_at" => nil)
        end
      end
    end

    context "with an entry the caller holds in another company" do
      let(:other_company) { create(:company, plan_tier: "free") }
      let(:other_project) { create(:project, billable: true, client: create(:client, company: other_company)) }

      before do
        create(:employment, company: other_company, user:)
        user.add_role :employee, other_company
        create(:project_member, project: other_project, user:)
        fake.register_company(id: other_company.id, edit_days: other_company.timesheet_edit_days)
        fake.register_project(id: other_project.id, company_id: other_company.id)
      end

      # "The CLI keeps its own-entries scope: the lookup is restricted to `user_id` equal to the actor and to the current company."
      it "answers 404 to a forwarded CLI update of that entry and sends no write" do
        foreign_entry_id = fake.add_entry(company_id: other_company.id, user_id: user.id, project_id: other_project.id,
                                          work_date: Date.current.iso8601, duration: 30.0, note: "Other workspace").fetch("id")

        send_request :patch, api_v1_cli_timesheet_entry_path(foreign_entry_id), params: {
          timesheet_entry: { project_id: project.id, duration_minutes: 15, work_date: Date.current.iso8601, note: "Moved" }
        }, headers: cli_headers

        expect(response).to have_http_status(:not_found)
        expect(cli_write_count("PATCH")).to eq(0)
        expect(fake.stored_entry(foreign_entry_id)["note"]).to eq("Other workspace")
        expect(fake.stored_entry(foreign_entry_id)["project_id"]).to eq(other_project.id)
      end
    end

    it "forwards a CLI create to Timekeeping as a cli entry of the signed-in user and answers the same entry JSON" do
      expect do
        send_request :post, api_v1_cli_timesheet_entries_path, params: {
          timesheet_entry: {
            project_id: project.id, duration_minutes: 45, work_date: Date.current.iso8601, note: "From the CLI",
            bill_status: "unbilled", source_metadata: { skill: "miru-cli" }
          }
        }, headers: cli_headers
      end.not_to change(TimesheetEntry, :count)

      expect(response).to have_http_status(:ok)
      stored = fake.stored_entry(json_response.dig("entry", "id"))
      expect(stored).to include("user_id" => user.id, "project_id" => project.id, "duration" => 45.0,
                                "note" => "From the CLI", "source" => "cli", "source_metadata" => { "skill" => "miru-cli" })
      expect(json_response["notice"]).to eq(I18n.t("timesheet_entry.create.message"))
      expect(json_response["entry"]).to include("project_id" => project.id, "duration" => 45.0, "source" => "cli",
                                                "type" => "timesheet")
    end

    it "forwards a CLI destroy of the user's own entry to Timekeeping and answers the same destroy JSON without touching local rows" do
      stored = fake.add_entry(company_id: company.id, user_id: user.id, project_id: project.id,
                              work_date: Date.current.iso8601, source: "cli")

      expect do
        send_request :delete, api_v1_cli_timesheet_entry_path(stored["id"]), headers: cli_headers
      end.not_to change(TimesheetEntry, :count)

      # "The CLI and MCP and agent writers go through Timekeeping::Gateway and keep their routes and JSON"
      expect(response).to have_http_status(:ok)
      expect(json_response).to eq("notice" => I18n.t("timesheet_entry.destroy.message"))
      deletes = fake.requests.select { |request| request[:method] == "DELETE" }
      expect(deletes.size).to eq(1)
      expect(deletes.first[:path]).to eq("/v1/companies/#{company.id}/entries/#{stored["id"]}")
      expect(fake.stored_entry(stored["id"])["discarded_at"]).not_to be_nil
    end
  end

  # No Timekeeping is configured here: the refusal comes before any store is chosen, and the update and
  # destroy act on a local legacy row.
  context "during a handoff" do
    it "refuses CLI create, update and destroy with 503 ownership_moving while handoff_step is set and reports actor_kind cli" do
      entry = create(:timesheet_entry, user:, project:, work_date: Date.current, duration: 30, note: "Before")
      TimekeepingOwnership.current.update!(handoff_step: "close_admission")
      params = { timesheet_entry: { project_id: project.id, duration_minutes: 15, work_date: Date.current.iso8601 } }

      event = assert_event_reported("Timekeeping::EntryWriteRefused") do
        send_request :post, api_v1_cli_timesheet_entries_path, params:, headers: cli_headers
      end
      expect(event[:payload].to_h[:data][:actor_kind].to_s).to eq("cli")

      # "When `handoff_step` is set, the gateway refuses entry writes, prepares and service commands with a retryable `503 ownership_moving`."
      [
        -> { send_request :post, api_v1_cli_timesheet_entries_path, params:, headers: cli_headers },
        -> { send_request :patch, api_v1_cli_timesheet_entry_path(entry), params:, headers: cli_headers },
        -> { send_request :delete, api_v1_cli_timesheet_entry_path(entry), headers: cli_headers }
      ].each do |write|
        write.call
        expect(response).to have_http_status(:service_unavailable)
        expect(json_response["reason"]).to eq("ownership_moving")
        expect(response.headers["Retry-After"]).to be_present
      end

      expect(TimesheetEntry.where(user:).count).to eq(1)
      expect(entry.reload).to have_attributes(note: "Before", duration: 30.0, discarded_at: nil)
    end
  end
end
